{'content': '// Towel hook with single M3 flat-head screw (countersunk)
// Units: mm

$fn = 72;

// ---------------- Parameters ----------------
plate_L = 50;          // length (X) of mounting plate
plate_W = 30;          // width (Y) of mounting plate
plate_T = 8;           // thickness (Z) of mounting plate
plate_R = 4;           // corner radius of plate (in XY)

// M3 flat head screw (typical)
hole_d = 3.4;          // clearance for M3
csink_top_d = 6.6;     // countersink diameter at surface
csink_depth = 2.8;     // depth of countersink cone

// Hook body
arm_r = 7.0;           // base radius for the arm (before scaling)
arm_sy = 1.25;         // Y scale factor (makes it wider)
arm_sz = 0.95;         // Z scale factor (slightly flatter)

// Path points for the hook (designed in printing orientation: plate on bed, hook on top)
// Later you can rotate in the slicer for wall-mounting.
arm_pts = [
    [-8,  0, plate_T-2],
    [ 0,  0, plate_T+4],
    [18,  0, plate_T+19],
    [40,  0, plate_T+13],
    [57,  0, plate_T+5],
    [57,  0, plate_T+1.5],
    [44,  0, plate_T+1.5],
    [44,  0, plate_T+12]  // small upturned lip
];

// ---------------- Helpers ----------------
module rounded_rect_2d(L, W, r){
    // Rounded rectangle centered at origin
    offset(r=r) square([L-2*r, W-2*r], center=true);
}

module plate(){
    linear_extrude(height=plate_T)
        rounded_rect_2d(plate_L, plate_W, plate_R);

    // subtle stiffening ridge on top face (keeps material near the screw)
    translate([0,0,plate_T])
        linear_extrude(height=2)
            offset(r=2)
                square([plate_L*0.58, plate_W*0.42], center=true);
}

module arm_node(p){
    translate(p)
        scale([1, arm_sy, arm_sz])
            sphere(r=arm_r);
}

module arm_sweep(points){
    union(){
        for(i=[0:len(points)-2]){
            hull(){
                arm_node(points[i]);
                arm_node(points[i+1]);
            }
        }
    }
}

module gusset(){
    // Reinforcing web between plate and the first part of the arm
    // (kept wide to increase bending strength at the root)
    hull(){
        translate([0,0,plate_T+0.01])
            linear_extrude(height=0.8)
                offset(r=2)
                    square([20, 18], center=true);

        translate([10,0,plate_T+11])
            scale([1, 1.15, 0.8])
                sphere(r=arm_r*0.95);
    }
}

module countersunk_m3(){
    // Through-hole
    translate([0,0,-0.1])
        cylinder(h=plate_T+2.2, d=hole_d);

    // Countersink from top (flat-head screw)
    translate([0,0,plate_T-csink_depth])
        cylinder(h=csink_depth+0.2, d1=csink_top_d, d2=hole_d);

    // Small clearance flat at the very top to avoid elephant-foot trapping the screw head
    translate([0,0,plate_T-0.35])
        cylinder(h=0.5, d=csink_top_d+0.4);
}

// ---------------- Model ----------------
module towel_hook(){
    difference(){
        union(){
            plate();
            arm_sweep(arm_pts);
            gusset();
        }
        countersunk_m3();
    }
}

towel_hook();
'}

